package com.visionerp.service; import com.visionerp.entity.Notification; import com.visionerp.repository.NotificationRepository; import org.springframework.messaging.simp.SimpMessagingTemplate; import org.springframework.stereotype.Service; import java.util.Map;
@Service public class NotificationService {private final NotificationRepository repo;private final SimpMessagingTemplate ws;public NotificationService(NotificationRepository r,SimpMessagingTemplate w){repo=r;ws=w;}public Notification send(String email,String type,String message){Notification n=new Notification();n.recipientEmail=email;n.type=type;n.message=message;repo.save(n);ws.convertAndSend("/topic/notifications/"+email,Map.of("type",type,"message",message));return n;}public java.util.List<Notification> list(String email){return repo.findTop30ByRecipientEmailOrderByCreatedAtDesc(email);}}
